/*
 * Geometry of "A Living Landscape" (LivingLandscape.jsx).
 *
 * The scene is a vector tracing of the approved hero reference (a 1748 x 900 image of a mountain sunset), taken layer by
 * layer so each layer can be lit and moved on its own: the far skyline, the central mountain, the dark hills and
 * mid-distance pines, and the black foreground (near pines and ground) are outlines found in the reference by edge
 * tracing and contour tracing (marching squares on its luminance); the fog banks and the wisps of cloud are soft ellipses
 * fitted to the lighter patches of the reference. All coordinates are in a 1710 x 380 view box: the reference card from
 * x = 12 to 1722 and from y = 510 (the cloud line) to the bottom edge, y = 890. The sun sits at (973, 271) and the
 * ridge hides all but its top cap. Stars and rain are generated below, from fixed seeds. Nothing here touches the DOM.
 */

export const VIEW_WIDTH = 1710
export const VIEW_HEIGHT = 380
/** Height of the land (pine tops to the bottom edge) in view-box units: the scale reference for the scene. */
export const LAND_UNITS = 242
/** The sun: centre and radius in view-box units. */
export const SUN = { x: 973, y: 271, r: 40 }
/** Centre of the glow around the sun, and its radii (the ellipse the sky gradient was fitted to). */
export const GLOW = { x: 973, y: 235, rx: 450, ry: 125 }

/** Small seeded random number generator (mulberry32): the same seed always gives the same sequence. */
function random(seed) {
  let state = seed | 0
  return () => {
    state = (state + 0x6d2b79f5) | 0
    let t = Math.imul(state ^ (state >>> 15), 1 | state)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

const round = (value) => Math.round(value * 10) / 10

