/**
 * The tracing runs straight for long stretches where a ridge fades into haze in the reference (the flanks of the central
 * mountain, long stretches of the skyline), which reads as geometric. Every long straight segment is roughened with
 * midpoint displacement, a few units at most, with its end points left exactly where they were, so the composition does
 * not move but the ridges stop being ruled lines. Segments along the edge of the view box are left alone.
 */
function roughen(path, seed) {
  const rand = random(seed)
  const onEdge = (a, b) => (a[0] <= 0.5 && b[0] <= 0.5) || (a[0] >= 1709 && b[0] >= 1709) || (a[1] >= 379 && b[1] >= 379)
  const split = (a, b, amp, out) => {
    const dx = b[0] - a[0]
    const dy = b[1] - a[1]
    const length = Math.hypot(dx, dy)
    if (length < 8 || amp < 0.3 || onEdge(a, b)) {
      out.push(b)
      return
    }
    const offset = (rand() - 0.5) * 2 * amp
    const mid = [(a[0] + b[0]) / 2 - (dy / length) * offset, (a[1] + b[1]) / 2 + (dx / length) * offset]
    split(a, mid, amp * 0.55, out)
    split(mid, b, amp * 0.55, out)
  }
  return path
    .split(/(?=[MZ])/)
    .map((sub) => {
      const closed = sub.endsWith('Z')
      const points = sub
        .replace(/[MZ]/g, '')
        .split('L')
        .map((token) => token.trim().split(/\s+/).map(Number))
        .filter((point) => point.length === 2 && point.every(Number.isFinite))
      if (points.length < 3) return sub
      const out = [points[0]]
      for (let i = 1; i < points.length; i += 1) {
        const length = Math.hypot(points[i][0] - points[i - 1][0], points[i][1] - points[i - 1][1])
        split(points[i - 1], points[i], Math.min(4.2, length * 0.05), out)
      }
      return `M${out.map(([x, y]) => `${round(x)} ${round(y)}`).join(' L')}${closed ? 'Z' : ''}`
    })
    .join(' ')
}

export const LAYERS = {
  skyline: roughen(TRACED.skyline, 11),
  mountain: roughen(TRACED.mountain, 23),
  dark: roughen(TRACED.dark, 37),
  black: TRACED.black,
}

