/* ---------------------------------------------------------------------------------------------- Stars */

const STAR_TINTS = ['#ffffff', '#ffffff', '#e3ecff', '#cfdcff', '#fff1dc']

/**
 * One set of stars across the whole hero: [x %, y %, radius px, opacity, colour]. They are not spread evenly: they gather
 * in loose clusters, most are small and faint and a few are large and bright (`power` skews the sizes), and there are
 * fewer of them right behind the copy. Each set twinkles on its own rhythm (see the stylesheet).
 */
function starSet({ seed, count, size: [minSize, maxSize], power, opacity: [minOpacity, maxOpacity] }) {
  const rand = random(seed)
  const clusters = Array.from({ length: 6 }, () => [rand() * 100, 4 + rand() * 60, 8 + rand() * 14])
  const stars = []
  for (let guard = 0; stars.length < count && guard < count * 80; guard += 1) {
    const x = rand() * 100
    const y = 2 + rand() * 66
    let density = 0.3
    for (const [cx, cy, spread] of clusters) density += 0.9 * Math.exp(-((x - cx) ** 2 + (y - cy) ** 2) / (2 * spread * spread))
    if (x > 20 && x < 80 && y > 26 && y < 64) density *= 0.55
    if (rand() > Math.min(1, density)) continue
    const weight = rand() ** power
    stars.push([round(x), round(y), round(minSize + (maxSize - minSize) * weight), round(minOpacity + (maxOpacity - minOpacity) * (0.35 * rand() + 0.65 * weight)), STAR_TINTS[Math.floor(rand() * STAR_TINTS.length)]])
  }
  return stars
}

export const STAR_SETS = [
  starSet({ seed: 101, count: 70, size: [0.45, 0.8], power: 1.5, opacity: [0.22, 0.55] }),
  starSet({ seed: 202, count: 38, size: [0.6, 1.1], power: 1.8, opacity: [0.4, 0.8] }),
  starSet({ seed: 303, count: 24, size: [0.9, 1.5], power: 2, opacity: [0.5, 0.95] }),
  starSet({ seed: 404, count: 20, size: [0.8, 1.4], power: 2, opacity: [0.45, 0.9] }),
  starSet({ seed: 505, count: 8, size: [1.5, 2.3], power: 1.2, opacity: [0.7, 1] }),
]

/* ---------------------------------------------------------------------------------------------- Rain */

/**
 * A repeating tile of slanted streaks, as a CSS `url()` value. The streaks slant by atan(width / height), so the tile
 * can be moved by (-width, +height) and land exactly on itself: a seamless loop of falling rain from one small image.
 */
function rainTile({ seed, width, height, count, minLength, maxLength, stroke, color, alpha }) {
  const rand = random(seed)
  const slant = width / height
  const lines = []
  for (let i = 0; i < count; i += 1) {
    const x = rand() * width
    const y = rand() * height
    const length = minLength + rand() * (maxLength - minLength)
    const opacity = (alpha * (0.5 + rand() * 0.5)).toFixed(2)
    // Copies one tile over wherever a streak crosses an edge, so nothing is cut off at the seam.
    for (const dx of [-width, 0, width]) {
      for (const dy of [-height, 0, height]) {
        const x1 = x + dx
        const y1 = y + dy
        const x2 = x1 - length * slant
        const y2 = y1 + length
        if (Math.max(x1, x2) < -2 || Math.min(x1, x2) > width + 2 || y2 < -2 || y1 > height + 2) continue
        lines.push(`<line x1="${x1.toFixed(1)}" y1="${y1.toFixed(1)}" x2="${x2.toFixed(1)}" y2="${y2.toFixed(1)}" stroke-opacity="${opacity}"/>`)
      }
    }
  }
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}"><g stroke="${color}" stroke-width="${stroke}" stroke-linecap="round">${lines.join('')}</g></svg>`
  return `url("data:image/svg+xml,${encodeURIComponent(svg)}")`
}

